export const normalizeName = name => name.replace(/([a-z0-9])([A-Z])/g,'$1_$2').replace(/([A-Z])([A-Z][a-z])/g,'$1_$2').replace(/^_+|_+$/g,'').toLowerCase();
const contains = (code, name) => new RegExp(`(?:^|[^\\w])${name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?![\\w])`).test(code);

function inferredBindings(lesson) {
 const result=[];
 for(const line of lesson.code.split('\n')) {
  const match=line.match(/^\s*(?:let\s+(?:mut\s+)?|(?:var|const|local|int|float|double|bool|boolean|string|auto)\s+)([A-Za-z_]\w*)\s*(?::[^=]+)?\s*=\s*(.+)/)
    ||line.match(/^\s*([A-Za-z_]\w*)\s*(?::[^=]+)?\s*(?::=|=)\s*(.+)/);
  if(match)result.push({name:match[1],kind:'local',initial:match[2].replace(/;$/,'')});
 }
 return result;
}

export function learningGuide(lesson) {
 if(!lesson)return null;
 const exercise=lesson.exerciseInfo, key=`${lesson.language}/${exercise?.slug || lesson.topicId}`;
 const active=(lesson.members || []).filter(m=>m.line<=lesson.line+lesson.code.split('\n').length && m.endLine>=lesson.line).map(m=>m.qualifiedName);
 const symbols=lesson.exerciseInfo?lesson.bindings || []:[...new Map([...inferredBindings(lesson),...(lesson.bindings || [])].map(b=>[b.name,b])).values()];
 const entries=new Map();
 for(const binding of symbols) {
  if(!contains(lesson.code,binding.name) || binding.owner && active.length && !active.includes(binding.owner))continue;
  const name=normalizeName(binding.name), meaning=specific[key]?.[name] || terms[name] || (binding.kind==='receiver'?'このメソッドの操作対象':null);
  const role=binding.kind==='parameter'?'呼び出し側から渡す引数':binding.kind==='receiver'?'操作対象':binding.kind==='iteration'?'繰り返しの位置':'このコード内で設定する値';
  const identity=JSON.stringify([binding.name,binding.kind,binding.type,meaning,binding.initial]);
  entries.set(identity,{...binding,meaning:meaning || role,role});
 }
 // Object receivers are meaningful even where the language makes them implicit.
 for(const name of ['self','this'])if(contains(lesson.code,name) && ![...entries.values()].some(b=>b.name===name))entries.set(name,{name,meaning:specific[key]?.[name] || terms[name],role:'操作対象'});
 for(const match of lesson.code.matchAll(/\b(self|this)\.([A-Za-z_]\w*)(?!\w|\s*\()/g)) {
  const name=match[0],field=normalizeName(match[2]),meaning=specific[key]?.[field] || terms[field];
  if(meaning)entries.set(name,{name,meaning,role:'オブジェクトが保持する値'});
 }
 return {purpose:exercise?.purposeJa || lesson.title,scope:lesson.scope || [],name:lesson.qualifiedName || '',notes:notes[key] || [],bindings:[...entries.values()]};
}
